package com.obysoft.faithOS.service;
import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;
@Service public class SensitiveDataService{private static final String PREFIX="enc:v1:";private final SecretKeySpec aes;private final byte[] hmacKey;private final SecureRandom random=new SecureRandom();public SensitiveDataService(@Value("${app.data-encryption-key}")String secret){if(secret==null||secret.length()<32)throw new IllegalStateException("DATA_ENCRYPTION_KEY must contain at least 32 characters.");try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8));aes=new SecretKeySpec(digest,"AES");hmacKey=digest;}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 public String encrypt(String value){if(value==null||value.isBlank()||value.startsWith(PREFIX))return value;return PREFIX+Base64.getEncoder().encodeToString(encryptRaw(value.getBytes(StandardCharsets.UTF_8)));}public String decrypt(String value){if(value==null||!value.startsWith(PREFIX))return value;return new String(decryptRaw(Base64.getDecoder().decode(value.substring(PREFIX.length()))),StandardCharsets.UTF_8);}public byte[] encrypt(byte[] value){if(value==null||value.length==0||encrypted(value))return value;return (PREFIX+Base64.getEncoder().encodeToString(encryptRaw(value))).getBytes(StandardCharsets.US_ASCII);}public byte[] decrypt(byte[] value){if(value==null||!encrypted(value))return value;String text=new String(value,StandardCharsets.US_ASCII);return decryptRaw(Base64.getDecoder().decode(text.substring(PREFIX.length())));}public String hash(String value){if(value==null||value.isBlank())return null;try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(hmacKey,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private byte[] encryptRaw(byte[] value){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,aes,new GCMParameterSpec(128,iv));byte[] out=c.doFinal(value),all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return all;}catch(GeneralSecurityException e){throw new IllegalStateException("Sensitive data encryption failed.",e);}}private byte[] decryptRaw(byte[] value){try{byte[] iv=Arrays.copyOfRange(value,0,12),body=Arrays.copyOfRange(value,12,value.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,aes,new GCMParameterSpec(128,iv));return c.doFinal(body);}catch(GeneralSecurityException e){throw new IllegalStateException("Sensitive data decryption failed.",e);}}private boolean encrypted(byte[] value){return new String(value,0,Math.min(value.length,PREFIX.length()),StandardCharsets.US_ASCII).startsWith(PREFIX);}}
